window.addEventListener('DOMContentLoaded', function () {
  const url = new URL(window.location.href);
  const pathnameMatch = url.pathname.includes('/pursuebetter');

  if (pathnameMatch && !url.searchParams.has('utm_athlete')) {
    url.searchParams.set('utm_athlete', 'pursue');
    window.history.replaceState({}, '', url.toString());
  }
});

