  function renderAwardsByRef(){
    var nodes = document.querySelectorAll('[data-award-ref]');
    nodes.forEach(function(node){
      var ref = (node.getAttribute('data-award-ref') || '').trim();
      var field = (node.getAttribute('data-award-field') || 'primary').trim();
      var rec = window.awardsByRef && window.awardsByRef[ref];
      if (rec && rec[field] && rec[field].length) {
        node.innerHTML = rec[field];       // render the HTML from HubDB
      } else {
        var fb = node.getAttribute('data-award-fallback');
        if (fb) node.textContent = fb;
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', renderAwardsByRef);
  } else {
    renderAwardsByRef();
  }
})();

