(function () {
  const SELECTORS = [
    "legend.hs-field-desc",
    ".portfolio-analysis-tool-disclosure"
  ];

  // Regex-based replacements (global + safe)
const REPLACEMENTS = [
  [/\$4\/mo\b/g, "$5/mo"],
  [/\$4 per month\b/gi, "$5 per month"],
  [/\$4 monthly\b/gi, "$5 monthly"],
  [/\$20,000(\+)?/g, "$24,000$1"],
  [/\$\s*250\s*\+/g, "$200+"]
];

  function replaceInTextNode(node) {
    const original = node.nodeValue;
    let updated = original;

    for (const [pattern, replacement] of REPLACEMENTS) {
      updated = updated.replace(pattern, replacement);
    }

    if (updated !== original) {
      node.nodeValue = updated;
    }
  }

  function apply(root = document) {
    for (const selector of SELECTORS) {
      const elements = root.querySelectorAll(selector);

      elements.forEach(el => {
        // Walk text nodes so we don't break links/markup inside containers
        const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, null);
        let node;
        while ((node = walker.nextNode())) {
          replaceInTextNode(node);
        }
      });
    }
  }

  // Initial runs
  apply();
  window.addEventListener("load", () => apply());

  // Watch for late loads / re-renders (common in HubSpot/forms/apps)
  const observer = new MutationObserver(mutations => {
    for (const m of mutations) {
      for (const node of m.addedNodes) {
        if (node && node.nodeType === 1) apply(node);
      }
    }
  });

  observer.observe(document.documentElement, { childList: true, subtree: true });

  // Safety stop to reduce overhead on very dynamic pages
  setTimeout(() => observer.disconnect(), 60000);
})();

